def size(t):
    k=t[0]
    if k in ('L','V'): return 1
    if k in ('Q','S','A'): return 1+size(t[1])
    return 1+size(t[1])+size(t[2])

def subterms(t,acc):
    acc.add(t)
    if t[0] in ('Q','S','A'): subterms(t[1],acc)
    elif t[0] in ('Fun','K'):
        subterms(t[1],acc); subterms(t[2],acc)
    return acc

def lift1(t):
    # lift_rec t 0 1
    def lr(t,k):
        if t[0]=='V': return V(t[1]+1)  # relocate i 0 1 always i+1
        if t[0]=='L': return L
        if t[0] in ('S','A'): return (t[0], lr(t[1],k))
        if t[0]=='Q': return Q(lr(t[1],k+1))
        return (t[0], lr(t[1],k), lr(t[2],k))
    return lr(t,0)

def subst0(t,u):
    # subst_rec t u 0, with simple relocate
    def test(k,i): return k<=i
    def reloc(i,k,n): return i+n if test(k,i) else i
    def insert(N,i,k):
        if test(k,i): return V(i-1) if i>k else (liftN(N,k) if i>=k else V(i))
        else: return V(i)
    def liftN(N,k):
        def lr(t):
            if t[0]=='V':
                return V(reloc(t[1],k,1) if test(k,t[1]) else t[1])
            if t[0]=='L': return L
            if t[0] in ('S','A'): return (t[0],lr(t[1]))
            if t[0]=='Q': return Q(lr(t[1]))
            return (t[0],lr(t[1]),lr(t[2]))
        return lr(N)
    def sr(t,k):
        if t[0]=='V':
            i=t[1]
            if test(k,i):
                # compare k i: if k<i -> left(left) => Var(i-1); if k=i -> left(right) => lift k N
                if k<i: return V(i-1)
                else: return liftN(u,k)
            else: return V(i)
        if t[0]=='L': return L
        if t[0] in ('S','A'): return (t[0],sr(t[1],k))
        if t[0]=='Q': return Q(sr(t[1],k+1))
        return (t[0],sr(t[1],k),sr(t[2],k))
    return sr(t,0)

