def solve_all(goal, subst, depth, assumptions, limit=None):
    """Generator of (subst, proof) for goal under subst with <=depth steps."""
    if depth<=0: return
    X=walk(goal[0],subst); Y=walk(goal[1],subst)
    # assumption
    for (sx,sy) in assumptions:
        ss=unify(X,sx,subst)
        if ss is not None:
            ss=unify(Y,sy,ss)
            if ss is not None:
                yield (ss, ('assume',sx,sy))
    # zero
    ss=unify(X,Y,subst)
    if ss is not None:
        yield (ss,('zero',))
    # trans via fresh middle M: all choices of M from solving first premise
    M=FR('m')
    for ss1,pf1 in solve_all((X,M), subst, depth-1, assumptions, limit):
        Y2=walk(Y,ss1); M2=walk(M,ss1)
        for ss2,pf2 in solve_all((M2,Y2), ss1, depth-1, assumptions, limit):
            yield (ss2,('trans',walk(M,ss2),pf1,pf2))
    # rules
    for (name,src,tgt,prems) in rule_instances(FR):
        ss=unify(X,src,subst)
        if ss is None: continue
        ss=unify(Y,tgt,ss)
        if ss is None: continue
        for ss2,spf in solve_prems_all(prems,ss,depth-1,assumptions,limit):
            yield (ss2,(name,)+tuple(spf))

def solve_prems_all(prems,subst,depth,assumptions,limit=None):
    if not prems:
        yield (subst,())
        return
    _tag,x,y=prems[0]
    x=norm(x,subst); y=norm(y,subst)
    for ss,pf in solve_all((x,y),subst,depth,assumptions,limit):
        for ss2,rest in solve_prems_all(prems[1:],ss,depth,assumptions,limit):
            yield (ss2,(pf,)+rest)

def show(t):
    t=walk(t,{})
