import sys
sys.setrecursionlimit(1000000)

class Var:
    __slots__=('name','rigid','id')
    def __init__(self,name,rigid,id): self.name=name; self.rigid=rigid; self.id=id
    def __repr__(self): return self.name if self.rigid else f"?{self.name}"

def isvar(t): return isinstance(t,Var)
def walk(t,subst):
    seen=0
    while isvar(t) and not t.rigid and t.id in subst:
        t=subst[t.id]; seen+=1
        if seen>10000: raise RuntimeError("loop")
    return t
def occurs(vid,t,subst):
    t=walk(t,subst)
    if isvar(t): return (not t.rigid) and t.id==vid
    if t[0] in ('L','V'): return False
    if t[0]=='lift': return occurs(vid,t[2],subst)
    if t[0]=='subst': return occurs(vid,t[1],subst) or occurs(vid,t[2],subst)
    if t[0] in ('Q','S','A'): return occurs(vid,t[1],subst)
    return occurs(vid,t[1],subst) or occurs(vid,t[2],subst)
def unify(a,b,subst):
    a=walk(a,subst); b=walk(b,subst)
    if isvar(a):
        if isvar(b) and a.id==b.id: return subst
        if a.rigid or occurs(a.id,b,subst): return None
        s=dict(subst); s[a.id]=b; return s
    if isvar(b):
        if b.rigid or occurs(b.id,a,subst): return None
        s=dict(subst); s[b.id]=a; return s
    if a[0]!=b[0]: return None
    if a[0]=='L': return subst
    if a[0]=='V': return subst if a[1]==b[1] else None
    if a[0]=='lift':
        if a[1]!=b[1]: return None
        return unify(a[2],b[2],subst)
    if a[0]=='subst':
        s=unify(a[1],b[1],subst)
        if s is None: return None
        return unify(a[2],b[2],s)
    if a[0] in ('Q','S','A'):
        return unify(a[1],b[1],subst)
    s=unify(a[1],b[1],subst)
    if s is None: return None
    return unify(a[2],b[2],s)

def lift_rec_term(t,k,n):
    if isvar(t): return ('lift',n,t)
    if t[0]=='L': return t
    if t[0]=='V':
        i=t[1]; return ('V', n+i if k<=i else i)
    if t[0]=='Q': return ('Q', lift_rec_term(t[1],k+1,n))
    if t[0]=='S': return ('S', lift_rec_term(t[1],k,n))
    if t[0]=='A': return ('A', lift_rec_term(t[1],k,n))
    if t[0] in ('F','K'): return (t[0], lift_rec_term(t[1],k,n), lift_rec_term(t[2],k,n))
    return ('lift',n,t)
def lift_term(n,t): return lift_rec_term(t,0,n)
def subst_rec_term(M,N,k):
    if isvar(M): return ('subst',M,N)
    if M[0]=='L': return M
    if M[0]=='V':
        i=M[1]
        if k<i: return ('V',i-1)
        if k==i: return lift_term(k,N)
        return ('V',i)
    if M[0]=='Q': return ('Q', subst_rec_term(M[1],N,k+1))
    if M[0]=='S': return ('S', subst_rec_term(M[1],N,k))
    if M[0]=='A': return ('A', subst_rec_term(M[1],N,k))
    if M[0] in ('F','K'): return (M[0], subst_rec_term(M[1],N,k), subst_rec_term(M[2],N,k))
    return ('subst',M,N)
def subst_term(M,N): return subst_rec_term(M,N,0)
def norm(t,subst):
    t=walk(t,subst)
    if isvar(t): return t
    if t[0]=='L' or t[0]=='V': return t
    if t[0]=='lift': return lift_term(t[1], norm(t[2],subst))
    if t[0]=='subst': return subst_term(norm(t[1],subst), norm(t[2],subst))
    if t[0] in ('Q','S','A'): return (t[0], norm(t[1],subst))
    if t[0] in ('F','K'): return (t[0], norm(t[1],subst), norm(t[2],subst))
    return t

class Fresh:
    def __init__(self): self.n=0
    def __call__(self,prefix='e'):
        self.n+=1; return Var(f"{prefix}{self.n}",False,self.n)
