Ts_list=list(Ts)
rel=set()
def add(a,b):
    if a in Ts and b in Ts and (a,b) not in rel:
        rel.add((a,b)); return True
    return False
for t in Ts: add(t,t)
for u in Ts:
    add(('L',), ('F',u,('S',u)))
    add(u, ('Q', lift(1,u)))
    add(u, ('A',u))
    add(('Q',('S',u)), ('S',('Q',u)))
    add(('Q',('A',u)), ('A',('Q',u)))
    for v in Ts:
        add(('S',u), ('F',v,('K',u,v)))
        add(('K',('L',),u), ('F',v,u))
        add(('A',('F',u,v)), ('F',u,v))
        add(('Q',('F',u,v)), ('F',('Q',u),('Q',v)))
        add(('Q',('K',u,v)), ('K',('Q',u),('Q',v)))
        add(('F',('K',('S',('F',u,('F',v,('V',0))))), ('F',u,v)), None) if False else None
for X in Ts:
    for N in Ts:
        R=subst(X,N)
        if R in Ts: add(('Q',X), R)

def closure():
    global rel
    it=0
    while True:
        it+=1
        succ={}; pred={}
        for a,b in rel:
            succ.setdefault(a,set()).add(b)
            pred.setdefault(b,set()).add(a)
        new=set()
        for a,bs in succ.items():
            for b in bs:
                new.add((('S',a),('S',b)))
                new.add((('A',a),('A',b)))
                new.add((('Q',a),('Q',b)))
        # binary monotone
        for a,bs in succ.items():
            for c,ds in succ.items():
                for b in bs:
                    for d in ds:
                        new.add((('K',a,c),('K',b,d)))
                # funty contravariant in first: b<=a, c<=d
                for b in pred.get(a,()):
                    for d in ds:
                        new.add((('F',a,c),('F',b,d)))
        # trans
        for a,bs in succ.items():
            for b in bs:
                for c in succ.get(b,()):
                    new.add((a,c))
        added=False
        for a,b in new:
            if a in Ts and b in Ts and (a,b) not in rel:
                rel.add((a,b)); added=True
        if not added: break
        if it%5==0: print("iter",it,"rel",len(rel), flush=True)
    print("closure iters",it,"rel",len(rel))
