# Ground term representation same as prove.py: tuples ('V',i),('L',),('Q',x),('S',x),('A',x),('F',a,b),('K',a,b)

def subterms(t, out=None):
    if out is None: out=set()
    out.add(t)
    if t[0] in ('V','L'): pass
    elif t[0] in ('Q','S','A'): subterms(t[1],out)
    else: subterms(t[1],out); subterms(t[2],out)
    return out

def lift1(t): return lift(1,t)

def candidates(goal, assumptions=()):
    C=set()
    base=set()
    for t in [goal[0],goal[1]]+[x for p in assumptions for x in p]:
        base |= subterms(t)
    C |= base
    # close under constructors with subterms
    added=True
    it=0
    while added and it<4:
        it+=1; added=False
        for a in list(C):
            for b in list(C):
                for t in [('Q',a),('S',a),('A',a),('F',a,b),('K',a,b)]:
                    if t not in C:
                        C.add(t); added=True
            for t in [('Q',a),('S',a),('A',a),lift1(a),subst(a,('V',0))]:
                if t not in C:
                    C.add(t); added=True
    return C

def rules_ground():
    """Return list (name, src, tgt, premises) as ground-rule templates with evars? We'll instantiate by matching."""
    # We'll instead enumerate rule schemas symbolically and unify with ground goal; reuse rule_instances with rigid names? 
