    pass

def prove(goal, C, memo, depth, assumptions=()):
    key=(goal, depth, tuple(sorted(assumptions)))
    if key in memo: return memo[key]
    X,Y=goal
    if X==Y:
        memo[key]=('zero',); return memo[key]
    for (sx,sy) in assumptions:
        if X==sx and Y==sy:
            memo[key]=('assume',sx,sy); return memo[key]
    if depth<=0:
        memo[key]=None; return None
    # trans over candidates
    for M in C:
        if M==X or M==Y: continue
        r1=prove((X,M),C,memo,depth-1,assumptions)
        if r1 is not None:
            r2=prove((M,Y),C,memo,depth-1,assumptions)
            if r2 is not None:
                pf=('trans',M,r1,r2); memo[key]=pf; return pf
    # structural rules by matching
    # sub_stem: X=S a, Y=S b
    if X[0]=='S' and Y[0]=='S':
        r=prove((X[1],Y[1]),C,memo,depth-1,assumptions)
        if r is not None: memo[key]=('stem',r); return memo[key]
    if X[0]=='A' and Y[0]=='A':
        r=prove((X[1],Y[1]),C,memo,depth-1,assumptions)
        if r is not None: memo[key]=('asf',r); return memo[key]
    if X[0]=='K' and Y[0]=='K':
        r1=prove((X[1],Y[1]),C,memo,depth-1,assumptions)
        if r1 is not None:
            r2=prove((X[2],Y[2]),C,memo,depth-1,assumptions)
            if r2 is not None: memo[key]=('fork',r1,r2); return memo[key]
    if X[0]=='F' and Y[0]=='F':
        # funty contravariant
        r1=prove((Y[1],X[1]),C,memo,depth-1,assumptions)
        if r1 is not None:
            r2=prove((X[2],Y[2]),C,memo,depth-1,assumptions)
            if r2 is not None: memo[key]=('funty',r1,r2); return memo[key]
    if X[0]=='Q' and Y[0]=='Q':
        r=prove((X[1],Y[1]),C,memo,depth-1,assumptions)
        if r is not None: memo[key]=('quant',r); return memo[key]
    # quant_stem
    if X[0]=='Q' and X[1][0]=='S' and Y[0]=='S' and Y[1][0]=='Q' and X[1][1]==Y[1][1]:
        memo[key]=('quant_stem',); return memo[key]
    if X[0]=='Q' and X[1][0]=='K' and Y[0]=='K' and Y[1][0]=='Q' and Y[2][0]=='Q' and X[1][1]==Y[1][1] and X[1][2]==Y[2][1]:
        memo[key]=('quant_fork',); return memo[key]
    if X[0]=='Q' and X[1][0]=='A' and Y[0]=='A' and Y[1][0]=='Q' and X[1][1]==Y[1][1]:
        memo[key]=('quant_asf',); return memo[key]
    if X[0]=='Q' and X[1][0]=='F' and Y[0]=='F' and Y[1][0]=='Q' and Y[2][0]=='Q' and X[1][1]==Y[1][1] and X[1][2]==Y[2][1]:
        memo[key]=('dist',); return memo[key]
    # sub_inst: X=Q ty, Y=subst ty u for some u in C
    if X[0]=='Q':
        for u in C:
            if subst(X[1],u)==Y:
                memo[key]=('inst',u); return memo[key]
    # sub_lift: Y=Q(lift 1 X)
    if Y[0]=='Q' and Y[1]==lift1(X):
        memo[key]=('lift',); return memo[key]
    # leaf_fun
    if X==('L',) and Y[0]=='F' and Y[1]==Y[2][1] and Y[2][0]=='S':
        memo[key]=('leaf_fun',); return memo[key]
    if X[0]=='S' and Y[0]=='F' and Y[1]==X[1] and Y[2][0]=='K' and Y[2][1]==X[1] and Y[2][2]==Y[1]:
        memo[key]=('stem_fun',); return memo[key]
    # fork rules
    if X[0]=='K' and X[1]==('L',) and Y[0]=='F' and Y[2]==X[2]:
        memo[key]=('fork_leaf',); return memo[key]
    if X[0]=='F' and X[1]==('L',) and Y[0]=='F' and Y[1]==X[1]:
        pass
    if X[0]=='A' and X[1][0]=='F' and Y==X[1]:
        memo[key]=('from_asf',); return memo[key]
    if Y[0]=='A' and Y[1]==X:
        memo[key]=('to_asf',); return memo[key]
    memo[key]=None; return None

def run(goalX,goalY,depth=10,assumptions=()):
    C=candidates((goalX,goalY),assumptions)
    memo={}
    r=prove((goalX,goalY),C,memo,depth,tuple(assumptions))
    return r

def showg(t):
    return show(t)
def ppg(pf,ind=0):
    pre='  '*ind
    if pf[0] in ('zero','assume','quant_stem','quant_fork','quant_asf','dist','leaf_fun','stem_fun','fork_leaf','from_asf','to_asf','lift'):
        return pre+pf[0]
    if pf[0]=='trans': return pre+'trans via '+show(pf[1])+'\n'+ppg(pf[2],ind+1)+'\n'+ppg(pf[3],ind+1)
    if pf[0]=='inst': return pre+'inst '+show(pf[1])
    return pre+pf[0]+'\n'+'\n'.join(ppg(q,ind+1) for q in pf[1:])

if __name__=='__main__':
    tests=[
      (('Q',('Q',('V',1))),('V',1)),
      (('Q',('Q',('V',1))),('Q',('V',1))),
      (('Q',('V',0)),('V',0)),
      (('Q',('V',1)),('V',1)),
      (('Q',('V',1)),('V',0)),
    ]
    for X,Y in tests:
        for d in range(1,13):
            r=run(X,Y,d)
            if r is not None:
                print(showg(X),'<:',showg(Y),'depth',d); print(ppg(r)); break
        else:
            print(showg(X),'<:',showg(Y),'NOT FOUND')
