base=[L]
types=set(base)
def add(t): types.add(t)
# build iteratively by constructor combinations of existing types limited
for it in range(3):
    cur=list(types)
    for t in cur:
        add(Q(t)); add(S(t)); add(A(t))
    cur=list(types)
    for a in cur:
        for b in cur:
            add(Fun(a,b)); add(K(a,b))
    # cap universe
    if len(types)>20000:
        break
print("universe",len(types))
# restrict to a smaller set for closure focus: terms with size <= 5
def size(t):
    if t[0] in ('L','V'): return 1
    if t[0] in ('Q','S','A'): return 1+size(t[1])
    return 1+size(t[1])+size(t[2])
