import sys
from collections import defaultdict
V=2
def sz(t):
    k=t[0]
    if k in ('V','L'): return 1
    if k in ('Q','S','A'): return 1+sz(t[1])
    return 1+sz(t[1])+sz(t[2])
def show(t):
    k=t[0]
    if k=='V': return f"v{t[1]}"
    if k=='L': return "L"
    if k=='Q': return f"Q({show(t[1])})"
    if k=='S': return f"S({show(t[1])})"
    if k=='A': return f"A({show(t[1])})"
    if k=='F': return f"F({show(t[1])},{show(t[2])})"
    if k=='K': return f"K({show(t[1])},{show(t[2])})"
def lift_rec(t,k,n):
    if t[0]=='V':
        i=t[1]; return ('V', n+i if k<=i else i)
    if t[0]=='L': return t
    if t[0]=='Q': return ('Q', lift_rec(t[1],k+1,n))
    if t[0]=='S': return ('S', lift_rec(t[1],k,n))
    if t[0]=='A': return ('A', lift_rec(t[1],k,n))
    return (t[0], lift_rec(t[1],k,n), lift_rec(t[2],k,n))
def lift(n,t): return lift_rec(t,0,n)
def insert_Var(N,i,k):
    if k<i: return ('V',i-1)
    if k==i: return lift(k,N)
    return ('V',i)
def subst_rec(M,N,k):
    if M[0]=='V': return insert_Var(N,M[1],k)
    if M[0]=='L': return M
    if M[0]=='Q': return ('Q', subst_rec(M[1],N,k+1))
    if M[0]=='S': return ('S', subst_rec(M[1],N,k))
    if M[0]=='A': return ('A', subst_rec(M[1],N,k))
    return (M[0], subst_rec(M[1],N,k), subst_rec(M[2],N,k))
def subst(M,N): return subst_rec(M,N,0)
def gen(N):
    bysize={}
    def rec(s):
        if s in bysize: return bysize[s]
        res=set()
        if s==1:
            res.add(('L',))
            for v in range(V): res.add(('V',v))
        else:
            for x in rec(s-1): res.add(('Q',x)); res.add(('S',x)); res.add(('A',x))
            for s1 in range(1,s-1):
                s2=s-1-s1
                for a in rec(s1):
                    for b in rec(s2):
                        res.add(('F',a,b)); res.add(('K',a,b))
        bysize[s]=res; return res
    out=set()
    for s in range(1,N+1): out |= rec(s)
    return out
def NF(t):
    k=t[0]
    if k in ('L','F'): return True
    if k=='A': return NF(t[1])
    if k=='Q': return NFQ(t[1])
    return False
def NFQ(t):
    k=t[0]
    if k in ('L','F'): return True
    if k in ('A','Q'): return NFQ(t[1])
    return False
def SF(t):
    k=t[0]
    if k in ('S','F'): return True
    if k=='A': return SF(t[1])
    if k=='Q': return SFQ(t[1])
    return False
def SFQ(t):
    k=t[0]
    if k in ('S','F'): return True
    if k in ('A','Q'): return SFQ(t[1])
    return False
N=int(sys.argv[1]) if len(sys.argv)>1 else 4
Ts=gen(N); Tl=list(Ts)
print("types",len(Ts),flush=True)
# additional constants/terms generated by rules may be size >N; only keep in Ts
rel=set()
succ=defaultdict(set); pred=defaultdict(set)
def add(a,b):
    if a in Ts and b in Ts and (a,b) not in rel:
        rel.add((a,b)); succ[a].add(b); pred[b].add(a); return True
    return False
def alltypes():
    for t in Ts: add(t,t)
alltypes()
def atomic():
    added=[]
    L=('L',)
    # leaf_fun
    for u in Ts:
        if add(L,('F',u,('S',u))): added.append(1)
    for X in list(Ts):
        if not NF(X): continue
        # lift
        if NFQ(lift(1,X)) and add(X,('Q',lift(1,X))): added.append(1)
        # to_asf
        if NF(('A',X)) and add(X,('A',X)): added.append(1)
        # from_asf
        if X[0]=='A' and X[1][0]=='F':
            if NF(X) and add(X,X[1]): added.append(1)
