import random
def V(n): return ('V',n)
L=('L',)
def Q(a): return ('Q',a)
def F(a,b): return ('F',a,b)
def S(a): return ('S',a)
def K(a,b): return ('K',a,b)
def A(a): return ('A',a)
def test(k,i): return k<=i
def relocate(i,k,n): return i+n if test(k,i) else i
def lift_rec(t,k,n):
    if t[0]=='V': return V(relocate(t[1],k,n))
    if t[0]=='L': return t
    if t[0] in ('S','A'): return (t[0],lift_rec(t[1],k,n))
    if t[0]=='Q': return Q(lift_rec(t[1],k+1,n))
    return (t[0],lift_rec(t[1],k,n),lift_rec(t[2],k,n))
def lift(n,t): return lift_rec(t,0,n)
def insert_Var(N,i,k):
    if test(k,i):
        if k<i: return V(i-1)
        else: return lift(k,N)
    else: return V(i)
def subst_rec(t,N,k):
    if t[0]=='V': return insert_Var(N,t[1],k)
    if t[0]=='L': return t
    if t[0] in ('S','A'): return (t[0],subst_rec(t[1],N,k))
    if t[0]=='Q': return Q(subst_rec(t[1],N,k+1))
    return (t[0],subst_rec(t[1],N,k),subst_rec(t[2],N,k))
def variant(pos,t,k):
    if t[0]=='V': return pos if k==t[1] else True
    if t[0]=='Q': return variant(pos,t[1],k+1)
    if t[0]=='F': return variant(not pos,t[1],k) and variant(pos,t[2],k)
    if t[0]=='L': return True
    if t[0]=='S': return variant(pos,t[1],k)
    if t[0]=='K': return variant(pos,t[1],k) and variant(pos,t[2],k)
    if t[0]=='A': return variant(pos,t[1],k)
def cov(t): return variant(True,t,0)
def gen(d):
    if d<=0: return random.choice([L,V(random.randrange(6))])
    c=random.choice(['Q','S','A','F','K','L','V'])
    if c=='L': return L
    if c=='V': return V(random.randrange(6))
    if c in ('Q','S','A'): return (c,gen(d-1))
    return (c,gen(d-1),gen(d-1))
