import random
def Var(i): return ('Var',i)
Leaf=('Leaf',)
def Quant(t): return ('Quant',t)
def Funty(a,b): return ('Funty',a,b)
def Stem(t): return ('Stem',t)
def Fork(a,b): return ('Fork',a,b)
def Asf(t): return ('Asf',t)
def relocate(i,k,n): return n+i if k<=i else i
def lift_rec(t,k,n):
    c=t[0]
    if c=='Var': return Var(relocate(t[1],k,n))
    if c=='Leaf': return Leaf
    if c=='Stem': return Stem(lift_rec(t[1],k,n))
    if c=='Asf': return Asf(lift_rec(t[1],k,n))
    if c=='Fork': return Fork(lift_rec(t[1],k,n),lift_rec(t[2],k,n))
    if c=='Funty': return Funty(lift_rec(t[1],k,n),lift_rec(t[2],k,n))
    if c=='Quant': return Quant(lift_rec(t[1],k+1,n))
def lift(n,t): return lift_rec(t,0,n)
def insert_Var(N,i,k):
    if k<i: return Var(i-1)
    if k==i: return lift(k,N)
    return Var(i)
def subst_rec(M,N,k):
    c=M[0]
    if c=='Var': return insert_Var(N,M[1],k)
    if c=='Leaf': return Leaf
    if c=='Stem': return Stem(subst_rec(M[1],N,k))
    if c=='Asf': return Asf(subst_rec(M[1],N,k))
    if c=='Fork': return Fork(subst_rec(M[1],N,k),subst_rec(M[2],N,k))
    if c=='Funty': return Funty(subst_rec(M[1],N,k),subst_rec(M[2],N,k))
    if c=='Quant': return Quant(subst_rec(M[1],N,k+1))
def subst(M,N): return subst_rec(M,N,0)
def variant(pos,k,t):
    c=t[0]
    if c=='Var': return pos if k==t[1] else True
    if c=='Leaf': return True
    if c=='Quant': return variant(pos,k+1,t[1])
    if c=='Funty': return variant(not pos,k,t[1]) and variant(pos,k,t[2])
    if c in ('Stem','Asf'): return variant(pos,k,t[1])
    if c=='Fork': return variant(pos,k,t[1]) and variant(pos,k,t[2])
def cov(t): return variant(True,0,t)
def ty_str(t):
    c=t[0]
    if c=='Var': return f"v{t[1]}"
    if c=='Leaf': return "*"
    if c=='Stem': return f"S({ty_str(t[1])})"
    if c=='Asf': return f"A({ty_str(t[1])})"
    if c=='Quant': return f"Q({ty_str(t[1])})"
    if c=='Fork': return f"F({ty_str(t[1])},{ty_str(t[2])})"
    if c=='Funty': return f"({ty_str(t[1])}->{ty_str(t[2])})"
def T(ty,uty): return Funty(uty,subst(ty,uty))
base=[Leaf,Var(0),Var(1),Var(2)]
Ts=base[:]
for a in base: Ts += [Stem(a),Asf(a),Quant(a)]
for a in base:
    for b in base: Ts += [Funty(a,b),Fork(a,b)]
print("num types",len(Ts))
random.seed(1)
bad=0
for _ in range(5000):
    ty=random.choice(Ts); uty=random.choice(Ts); w=random.choice(Ts); k=random.randrange(3)
    typ=subst_rec(ty,w,k+1); utyp=subst_rec(uty,w,k)
    lhs=subst_rec(T(ty,uty),w,k); rhs=T(typ,utyp)
    if lhs!=rhs:
        bad+=1
        if bad<=5: print("T MISMATCH",ty_str(ty),ty_str(uty),ty_str(w),k); print(" lhs",ty_str(lhs)," rhs",ty_str(rhs)); print(" typ",ty_str(typ)," utyp",ty_str(utyp))
print("T mismatches",bad,"/5000")
bad=0; tested=0; ex=[]
for ty in Ts:
    if not cov(ty): continue
    for w in Ts:
        for k in range(4):
            typ=subst_rec(ty,w,k+1); tested+=1
            if not cov(typ):
                bad+=1
                if len(ex)<10: ex.append((ty,w,k,typ))
print("cov failures",bad,"of",tested)
for ty,w,k,typ in ex:
    print(" COVFAIL",ty_str(ty),"w",ty_str(w),"k",k,"typ",ty_str(typ))
