import sys, time
sys.setrecursionlimit(100000)
# reuse type gen/subst from search.py
exec(open('/tmp/s/model/search.py').read().split("Ts=gen")[0])
N=int(sys.argv[1]) if len(sys.argv)>1 else 4
VARS=tuple(range(4))
Ts=gen(N,VARS)
Ts_list=list(Ts)
idx={t:i for i,t in enumerate(Ts_list)}
n=len(Ts_list)
print("types",n,flush=True)
L=('L',)
def addpair(succ,a,b):
    ia=idx.get(a); ib=idx.get(b)
    if ia is not None and ib is not None:
        bit=1<<ib
        if not (succ[ia]&bit):
            succ[ia]|=bit; return True
    return False
succ=[0]*n
changed=True
round=0
start=time.time()
while changed:
    round+=1; changed=False
    # reflexive
    for i in range(n):
        if not (succ[i]>>i)&1:
            succ[i]|=1<<i; changed=True
    # unary congruences from all pairs
    for a in range(n):
        ta=Ts_list[a]; bs=succ[a]
        # iterate set bits
        x=bs
        while x:
            lb=x & -x; b=lb.bit_length()-1; x-=lb
            tb=Ts_list[b]
            # S/A/Q
            for ctor in ('S','A','Q'):
                na=(ctor,ta); nb=(ctor,tb)
                if addpair(succ,na,nb): changed=True
    # binary monotone K and F
    # precompute successors as lists for components? iterate over all K/F source types
    for ia,ta in enumerate(Ts_list):
        if ta[0]=='K':
            a,c=ta[1],ta[2]
            iaa=idx[a]; icc=idx[c]
            bs=succ[iaa]; ds=succ[icc]
            # convert to lists
            bl=[j for j in range(n) if (bs>>j)&1]
            dl=[j for j in range(n) if (ds>>j)&1]
            for j in bl:
                for k in dl:
                    nt=('K',Ts_list[j],Ts_list[k])
                    if addpair(succ,ta,nt): changed=True
        elif ta[0]=='F':
            a,c=ta[1],ta[2]
            iaa=idx[a]; icc=idx[c]
            # pred[a]: b with b<:a ; succ[c]
            bl=[j for j in range(n) if (succ[j]>>iaa)&1]
            ds=succ[icc]
            dl=[j for j in range(n) if (ds>>j)&1]
            for j in bl:
                for k in dl:
                    nt=('F',Ts_list[j],Ts_list[k])
                    if addpair(succ,ta,nt): changed=True
    # special quant rules and base rules
    def add(a,b,why=''):
        nonlocal changed
        if addpair(succ,a,b): changed=True
    for t in Ts_list:
        if t[0]=='S':
            u=t[1]
            add(L,('F',u,('S',u)))
            for v in Ts_list:
                add(('S',u),('F',v,('K',u,v)))
        if t[0]=='Q':
            z=t[1]
            add(t,('Q',lift(1,t)))
            if z[0]=='S': add(t,('S',('Q',z[1])))
            if z[0]=='K': add(t,('K',('Q',z[1]),('Q',z[2])))
            if z[0]=='A': add(t,('A',('Q',z[1])))
            if z[0]=='F': add(t,('F',('Q',z[1]),('Q',z[2])))
            if z[0]=='F':
                for u in Ts_list:
                    add(t,subst(z,u))
            else:
                for u in Ts_list:
                    add(t,subst(z,u))
        if t[0]=='K':
            a,b=t[1],t[2]
            if a==L: 
                for v in Ts_list: add(t,('F',v,b))
            for v in Ts_list:
                if a[0]=='A' and a[1]==('F',v,b): add(t,('F',v,b))
                if a[0]=='F' and a[1]==('F',v,('F',b,('V',0))): add(t,('F',v,('V',0)))
        if t[0]=='A':
            z=t[1]
            if z[0]=='F': add(t,z)
        # bffs/bfff source shapes are K with Asf second; skip exact unless matching
    # trans closure bitset
    # Warshall
    for k in range(n):
        sk=succ[k]
        if sk==0: continue
        bit=1<<k
        for i in range(n):
            if succ[i]&bit:
                ns=succ[i]|sk
                if ns!=succ[i]:
                    succ[i]=ns; changed=True
    print("round",round,"pairs",sum(x.bit_count() for x in succ),"time",time.time()-start,flush=True)
    if time.time()-start>240: print("TIMEOUT"); break
Lidx=idx[L]
def rel(a,b):
    ia=idx.get(a); ib=idx.get(b)
    return ia is not None and ib is not None and ((succ[ia]>>ib)&1)
# D1
badD1=[]
for ia in range(n):
    if not (succ[Lidx]>>ia)&1: continue
    b=Ts_list[ia]
    if b[0]=='F':
        u,ty=b[1],b[2]
        if not rel(('S',u),ty): badD1.append((u,ty))
print("D1 bad",len(badD1),[(show(u),show(t)) for u,t in badD1[:10]])
# D2
badD2=[]
for ia in range(n):
    a=Ts_list[ia]
    if a[0]!='S': continue
    A=a[1]
    x=succ[ia]
    for ib in range(n):
        if not (x>>ib)&1: continue
        b=Ts_list[ib]
        if b[0]=='F':
            u,ty=b[1],b[2]
            if not rel(('K',A,u),ty): badD2.append((A,u,ty))
