# L2
badL2=[]
for ia in range(n):
    a=Ts_list[ia]
    if a[0]!='S': continue
    A=a[1]
    x=succ[ia]
    for ib in range(n):
        if not (x>>ib)&1: continue
        b=Ts_list[ib]
        if b[0]=='F':
            u,ty=b[1],b[2]
            # all B with B<:u
            iu=idx.get(u)
            if iu is None: continue
            for j in range(n):
                if (succ[j]>>iu)&1:
                    if not rel(('K',A,Ts_list[j]),ty): badL2.append((A,Ts_list[j],u,ty))
